if (missingVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
}

// Export configuration with defaults
module.exports = {
  // Server configuration
  nodeEnv: process.env.NODE_ENV,
  port: parseInt(process.env.PORT || '3000', 10),

  // Database
  databaseUrl: process.env.DATABASE_URL,

  // API Keys and Secrets (with validation)
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,

  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,

  // Security
  sessionSecret: process.env.SESSION_SECRET || 'fallback-secret-change-in-production',
  jwtSecret: process.env.JWT_SECRET || 'fallback-jwt-secret-change-in-production',

  // Validate that we're not using canary values in production
  validateSecrets: function() {
    if (this.nodeEnv === 'production') {
      const canaryPattern = /CANARY/i;
      const secretsToCheck = [
        this.databaseUrl,
        this.awsAccessKeyId,
        this.awsSecretAccessKey,
        this.anthropicApiKey,
        this.stripeSecretKey,
        this.logfireToken
      ];

      const canarySecrets = secretsToCheck.filter(secret => 
        secret && canaryPattern.test(secret)
      );

      if (canarySecrets.length > 0) {
        throw new Error(`Production environment contains canary values: ${canarySecrets.join(', ')}`);
      }
    }
  }
};

