// Secure secret management utility
// DO NOT load .env files directly in production!

const { config } = require('dotenv');

class SecretManager {
  constructor() {
    this.secrets = {};
    this.isProduction = process.env.NODE_ENV === 'production';
    this.initialize();
  }

  async initialize() {
    if (!this.isProduction) {
      // Load from .env file only in development
      config();
    }

    await this.loadSecrets();
  }

  async loadSecrets() {
    if (this.isProduction) {
      // In production, load from secure secrets manager
      await this.loadFromSecretsManager();
    } else {
      // In development, load from process.env (already loaded via dotenv)
      this.loadFromEnvironment();
    }
  }

  async loadFromSecretsManager() {
    // Implementation for AWS Secrets Manager, HashiCorp Vault, etc.
    // Example for AWS Secrets Manager:
    /*
    const { SecretsManager } = require('aws-sdk');
    const secretsManager = new SecretsManager();

    try {
      const secret = await secretsManager.getSecretValue({
        SecretId: process.env.SECRETS_ARN
      }).promise();

      this.secrets = JSON.parse(secret.SecretString);
    } catch (error) {
      console.error('Failed to load secrets from manager:', error);
      throw new Error('Secrets loading failed');
    }
    */

    // For demo purposes, we'll use environment variables
    // In real production, implement proper secrets manager integration
    this.loadFromEnvironment();
  }

  loadFromEnvironment() {
    this.secrets = {
      databaseUrl: process.env.DATABASE_URL,
      jwtSecret: process.env.JWT_SECRET,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      apiKeys: {
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY,
        logfire: process.env.LOGFIRE_TOKEN
      }
    };

    this.validateSecrets();
  }

  validateSecrets() {
    const requiredSecrets = ['databaseUrl', 'jwtSecret'];
    const missing = [];

    requiredSecrets.forEach(secret => {
      if (!this.secrets[secret]) {
        missing.push(secret);
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate secret formats
    if (this.secrets.jwtSecret && this.secrets.jwtSecret.length < 32) {
      throw new Error('JWT secret must be at least 32 characters long');
    }
  }

  getSecret(key) {
    const secret = this.secrets[key];
    if (!secret) {
      throw new Error(`Secret not found: ${key}`);
    }
    return secret;
  }

  getDatabaseUrl() {
    return this.getSecret('databaseUrl');
  }

  getJwtSecret() {
    return this.getSecret('jwtSecret');
  }

  getApiKey(service) {
    return this.secrets.apiKeys?.[service];
  }
}

// Singleton instance
module.exports = new SecretManager();

