// Secure secret management with validation and fallback strategies
const AWS = require('aws-sdk');

class SecretManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  // Initialize secret manager
  async init() {
    try {
      await this.loadSecrets();
      this.initialized = true;
      console.log('Secret manager initialized successfully');
    } catch (error) {
      console.error('Failed to initialize secret manager:', error.message);
      throw error;
    }
  }

  // Load secrets from various sources with priority
  async loadSecrets() {
    // Priority 1: AWS Secrets Manager (production)
    if (process.env.AWS_REGION && process.env.AWS_SECRET_NAME) {
      await this.loadFromAwsSecretsManager();
    }

    // Priority 2: Environment variables (development/staging)
    this.loadFromEnvironment();

    // Priority 3: Local .env file (development only)
    if (process.env.NODE_ENV === 'development') {
      this.loadFromDotEnv();
    }

    // Validate required secrets
    this.validateRequiredSecrets();
  }

  async loadFromAwsSecretsManager() {
    try {
      const secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION
      });

      const data = await secretsManager.getSecretValue({
        SecretId: process.env.AWS_SECRET_NAME
      }).promise();

      const secrets = JSON.parse(data.SecretString);
      Object.entries(secrets).forEach(([key, value]) => {
        this.secrets.set(key, value);
      });

      console.log('Secrets loaded from AWS Secrets Manager');
    } catch (error) {
      console.error('AWS Secrets Manager error:', error.message);
      throw error;
    }
  }

  loadFromEnvironment() {
    const secretKeys = [
      'JWT_SECRET', 'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 
      'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN'
    ];

    secretKeys.forEach(key => {
      if (process.env[key]) {
        this.secrets.set(key, process.env[key]);
      }
    });
  }

  loadFromDotEnv() {
    // dotenv would already be loaded by app.js
    // This just ensures we capture .env values
    const secretKeys = [
      'JWT_SECRET', 'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 
      'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN'
    ];

    secretKeys.forEach(key => {
      if (process.env[key] && !this.secrets.has(key)) {
        this.secrets.set(key, process.env[key]);
      }
    });
  }

  validateRequiredSecrets() {
    const requiredSecrets = ['JWT_SECRET'];
    const missing = [];

    requiredSecrets.forEach(secret => {
      if (!this.secrets.has(secret) || !this.secrets.get(secret)) {
        missing.push(secret);
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  getSecret(key) {
    if (!this.initialized) {
      throw new Error('Secret manager not initialized');
    }

    const value = this.secrets.get(key);
    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }

    return value;
  }

  // Safe method for logging (masks sensitive data)
  getSecretForLogging(key) {
    try {
      const value = this.getSecret(key);
      return `${key.substring(0, 4)}...${key.substring(key.length - 4)}`;
    } catch {
      return 'NOT_SET';
    }
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = secretManager;

